print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"\n{i}: '{inp}' -> '{out}'")
        # Find what changed
        if len(inp) < len(out):
            # Something was inserted
            print(f"  Length increased from {len(inp)} to {len(out)}")
            # Look for common prefix/suffix
            min_len = min(len(inp), len(out))
            prefix_match = 0
            suffix_match = 0
            for j in range(min_len):
                if inp[j] == out[j]:
                    prefix_match += 1
                else:
                    break
            for j in range(1, min_len + 1):
                if inp[-j] == out[-j]:
                    suffix_match += 1
                else:
                    break
            print(f"  Prefix match: {prefix_match}, Suffix match: {suffix_match}")
        else:
            print(f"  Length unchanged or decreased")

